#!/usr/bin/env python3
"""
YouTube 영상의 자막/트랜스크립트를 추출하는 스크립트.

추출 순서:
  1. youtube-transcript-api (기존 자막)
  2. yt-dlp 자막 파일 다운로드
  3. defuddle CLI (InnerTube API 방식, IP 차단 우회 가능)
  4. yt-dlp 오디오 다운로드 → Gemini API 전사 (자막 없을 때)

Usage: python get_transcript.py <youtube_url>
환경변수: GEMINI_API_KEY 또는 GOOGLE_API_KEY
"""

import sys
import json
import re
import subprocess
import os
import tempfile
import time


def extract_video_id(url):
    """YouTube URL에서 video ID 추출"""
    patterns = [
        r'(?:v=)([^&\n?#]+)',
        r'(?:youtu\.be/)([^&\n?#]+)',
        r'(?:shorts/)([^&\n?#]+)',
    ]
    for pattern in patterns:
        match = re.search(pattern, url)
        if match:
            return match.group(1)
    return None


def get_video_info(url):
    """yt-dlp로 영상 제목 및 설명 추출"""
    try:
        result = subprocess.run(
            ['yt-dlp', '--print', '%(title)s|||%(description)s|||%(channel)s', '--no-playlist', url],
            capture_output=True, text=True, timeout=30
        )
        if result.returncode == 0 and result.stdout.strip():
            parts = result.stdout.strip().split('|||')
            return {
                'title': parts[0] if len(parts) > 0 else '',
                'description': parts[1] if len(parts) > 1 else '',
                'channel': parts[2] if len(parts) > 2 else '',
            }
    except Exception:
        pass
    return {'title': '', 'description': '', 'channel': ''}


def get_transcript_via_api(url):
    """youtube-transcript-api를 사용하여 자막 추출"""
    try:
        from youtube_transcript_api import YouTubeTranscriptApi

        video_id = extract_video_id(url)
        if not video_id:
            return None, "Could not extract video ID"

        api = YouTubeTranscriptApi()

        # 한국어 우선, 영어 폴백
        for langs in [['ko'], ['en'], ['ko', 'en']]:
            try:
                fetched = api.fetch(video_id, languages=langs)
                full_text = ' '.join([t.text for t in fetched])
                if full_text.strip():
                    return full_text, None
            except Exception:
                continue

        # 자동 생성 자막 포함해서 재시도 (언어 제한 없이)
        try:
            transcript_list = api.list(video_id)
            for transcript in transcript_list:
                try:
                    fetched = transcript.fetch()
                    full_text = ' '.join([t.text for t in fetched])
                    if full_text.strip():
                        return full_text, None
                except Exception:
                    continue
        except Exception:
            pass

        return None, "No transcript available"
    except ImportError:
        return None, "youtube-transcript-api not installed"


def get_transcript_via_ytdlp_sub(url):
    """yt-dlp로 자막 파일을 직접 다운로드하여 추출"""
    with tempfile.TemporaryDirectory() as tmpdir:
        subprocess.run(
            [
                'yt-dlp',
                '--write-auto-sub',
                '--write-sub',
                '--sub-langs', 'ko.*,en.*',
                '--skip-download',
                '--output', os.path.join(tmpdir, 'video'),
                '--no-playlist',
                url
            ],
            capture_output=True, text=True, timeout=60
        )

        for fname in os.listdir(tmpdir):
            if fname.endswith('.vtt') or fname.endswith('.srt'):
                fpath = os.path.join(tmpdir, fname)
                with open(fpath, 'r', encoding='utf-8') as f:
                    raw = f.read()
                lines = []
                for line in raw.split('\n'):
                    line = line.strip()
                    if '-->' in line or line.startswith('WEBVTT') or line.isdigit():
                        continue
                    line = re.sub(r'<[^>]+>', '', line)
                    if line:
                        lines.append(line)
                text = ' '.join(lines)
                if text.strip():
                    return text, None

    return None, "No subtitle file found via yt-dlp"


def download_audio(url, tmpdir):
    """yt-dlp로 오디오를 m4a/mp3로 다운로드. 파일 경로 반환."""
    out_template = os.path.join(tmpdir, 'audio.%(ext)s')
    result = subprocess.run(
        [
            'yt-dlp',
            '-f', 'bestaudio[ext=m4a]/bestaudio/best',
            '--extract-audio',
            '--audio-format', 'm4a',
            '--audio-quality', '5',        # 낮은 품질로 파일 크기 줄이기
            '--output', out_template,
            '--no-playlist',
            url
        ],
        capture_output=True, text=True, timeout=300
    )
    if result.returncode != 0:
        return None, f"yt-dlp audio download failed: {result.stderr[:300]}"

    for fname in os.listdir(tmpdir):
        if fname.startswith('audio.'):
            return os.path.join(tmpdir, fname), None

    return None, "Audio file not found after download"


def get_transcript_via_defuddle(url):
    """defuddle CLI를 사용하여 YouTube 자막 추출 (InnerTube API 방식)"""
    try:
        result = subprocess.run(
            ['npx', '--yes', 'defuddle', 'parse', url, '--json'],
            capture_output=True, text=True, timeout=60
        )
        if result.returncode != 0 or not result.stdout.strip():
            return None, f"defuddle failed: {result.stderr[:200]}"

        data = json.loads(result.stdout)
        content = data.get('content', '').strip()
        if not content:
            return None, "defuddle returned empty content"

        # HTML 태그 제거 후 텍스트만 추출
        text = re.sub(r'<[^>]+>', ' ', content)
        text = re.sub(r'\s+', ' ', text).strip()
        if text:
            return text, None

        return None, "defuddle content was empty after parsing"
    except json.JSONDecodeError as e:
        return None, f"defuddle JSON parse error: {e}"
    except FileNotFoundError:
        return None, "npx not found. Node.js가 설치되어 있어야 합니다"
    except subprocess.TimeoutExpired:
        return None, "defuddle timeout"
    except Exception as e:
        return None, f"defuddle error: {e}"


def get_transcript_via_gemini(url):
    """오디오 다운로드 후 Gemini API로 전사"""
    api_key = os.environ.get('GEMINI_API_KEY') or os.environ.get('GOOGLE_API_KEY')
    if not api_key:
        return None, "GEMINI_API_KEY 또는 GOOGLE_API_KEY 환경변수가 설정되지 않았습니다"

    try:
        import google.generativeai as genai
    except ImportError:
        return None, "google-generativeai not installed. Run: pip install google-generativeai"

    genai.configure(api_key=api_key)

    with tempfile.TemporaryDirectory() as tmpdir:
        print(json.dumps({'status': 'downloading_audio', 'message': '오디오 다운로드 중...'}), flush=True)

        audio_path, err = download_audio(url, tmpdir)
        if not audio_path:
            return None, err

        file_size_mb = os.path.getsize(audio_path) / (1024 * 1024)
        print(json.dumps({'status': 'uploading', 'message': f'Gemini에 오디오 업로드 중... ({file_size_mb:.1f}MB)'}), flush=True)

        # Gemini Files API에 업로드
        try:
            uploaded = genai.upload_file(audio_path, mime_type='audio/mp4')
        except Exception as e:
            return None, f"Gemini 파일 업로드 실패: {e}"

        # 업로드 처리 대기
        max_wait = 120
        waited = 0
        while waited < max_wait:
            file_state = genai.get_file(uploaded.name)
            if file_state.state.name == 'ACTIVE':
                break
            if file_state.state.name == 'FAILED':
                return None, "Gemini 파일 처리 실패"
            time.sleep(3)
            waited += 3

        if waited >= max_wait:
            return None, "Gemini 파일 처리 시간 초과"

        print(json.dumps({'status': 'transcribing', 'message': 'Gemini가 음성을 텍스트로 변환 중...'}), flush=True)

        # 전사 요청
        try:
            gemini_models = [
                'gemini-2.5-flash',
                'gemini-2.5-flash-lite',
                'gemini-3-flash-preview',
                'gemini-1.5-flash-latest',
                'gemini-1.5-pro-latest',
            ]
            model = None
            last_err = None
            for model_name in gemini_models:
                try:
                    model = genai.GenerativeModel(model_name)
                    break
                except Exception as e:
                    last_err = e
                    continue
            if model is None:
                return None, f"Gemini 모델 초기화 실패: {last_err}"
            response = model.generate_content([
                uploaded,
                (
                    "이 오디오의 내용을 전체 전사해주세요. "
                    "한국어로 말하는 내용은 한국어 그대로, 영어는 영어 그대로 전사하세요. "
                    "타임스탬프 없이 말한 내용만 순서대로 작성해주세요. "
                    "화자 구분이 필요하면 '[화자1]', '[화자2]' 형식으로 표시하세요."
                )
            ])
            transcript = response.text.strip()
        except Exception as e:
            return None, f"Gemini 전사 요청 실패: {e}"
        finally:
            # 업로드 파일 삭제
            try:
                genai.delete_file(uploaded.name)
            except Exception:
                pass

        if transcript:
            return transcript, None
        return None, "Gemini 전사 결과가 비어있습니다"


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print(json.dumps({'success': False, 'error': 'Usage: python get_transcript.py <youtube_url>'}))
        sys.exit(1)

    url = sys.argv[1]
    method_used = None

    # 영상 정보 먼저 가져오기
    info = get_video_info(url)

    # 1단계: youtube-transcript-api (기존 자막)
    transcript, error = get_transcript_via_api(url)
    if transcript:
        method_used = 'youtube-transcript-api'

    # 2단계: yt-dlp 자막 파일
    if not transcript:
        transcript, error = get_transcript_via_ytdlp_sub(url)
        if transcript:
            method_used = 'yt-dlp-subtitle'

    # 3단계: defuddle CLI (InnerTube API 방식)
    if not transcript:
        transcript, error = get_transcript_via_defuddle(url)
        if transcript:
            method_used = 'defuddle'

    # 4단계: Gemini API 오디오 전사
    if not transcript:
        transcript, error = get_transcript_via_gemini(url)
        if transcript:
            method_used = 'gemini-audio-transcription'

    if transcript:
        print(json.dumps({
            'success': True,
            'transcript': transcript,
            'method': method_used,
            'video_id': extract_video_id(url),
            'title': info.get('title', ''),
            'description': info.get('description', '')[:2000],
            'channel': info.get('channel', ''),
            'url': url
        }, ensure_ascii=False))
    else:
        print(json.dumps({
            'success': False,
            'error': error or 'All transcript methods failed',
            'title': info.get('title', ''),
            'channel': info.get('channel', ''),
            'url': url
        }, ensure_ascii=False))
